// Owner: data (wave-3 integration, 21 Nov 2026). Checks the wave-3 data (src/lib/data/wave3, GENERATED by
// research/wave3/build.py) wired into the catalogue like wave 2's: ids, SKILLS, COURSES, JOBS, GUIDES, companies and the
// merged career families (../careers.ts), with the knowledge-plus additions. The same rules as ../wave2/wave2.test.ts, and:
// no bare «Swift» alias (SWIFT bank payments), every wave-3 job after every older one in JOB_IDS (no tie of the demo's
// reveal moves), no salary row printed in AED quoted as SAR, and no day of collection in what «دليلك» is given.
import { describe, expect, it } from "vitest";

import { cleanJobTitle, COMPANIES, COMPANY_TILES, COURSES, getGuide, JOBS, SAMPLE_CV_BODY, SKILLS } from "@/lib/data";
import { ADVANCED_WORDS, MIDDLE_WORDS } from "@/lib/brain/cv/local-analyser";
import { jobsAtCompany } from "@/lib/engine/companies";
import { COMPANY_IDS, COURSE_IDS, FIELD_IDS, JOB_FIELD_IDS, JOB_IDS, SKILL_IDS } from "@/lib/ids";
import { findKeywords, normalizeText } from "@/lib/text/normalize";

import { CAREER_FAMILIES, CAREER_FAMILY_IDS, careersIndexForModel, ENTRY_ROUTES, knowledgeForModel, saudizationForModel } from "../careers";
import { WAVE2_JOB_IDS } from "../wave2/jobs";
import { WAVE3_COURSE_IDS, WAVE3_COURSES } from "./courses";
import { WAVE3_GUIDES } from "./guides";
import { WAVE3_JOB_IDS, WAVE3_JOBS } from "./jobs";
import { WAVE3_CAREER_FAMILIES, WAVE3_ENTRY_ROUTES, WAVE3_FAMILY_IDS, WAVE3_FAMILY_PLUS } from "./knowledge";
import { WAVE3_FIELDS, WAVE3_SKILL_IDS, WAVE3_SKILLS } from "./skills";

// ─── helpers (the same lenient reading as ../wave2/wave2.test.ts) ─────────────────────────────────────────────────

function norm(text: string): string {
  return text
    .normalize("NFKC")
    .replace(/[ً-ٰٟـ‌-‏‪-‮]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .toLowerCase();
}

function words(text: string): string[] {
  return norm(text)
    .split(/[^\p{L}\p{N}+#]+/u)
    .filter((w) => w.length > 0);
}

function readings(word: string): string[] {
  const out = new Set<string>([word]);
  const stripAl = (w: string) => (w.startsWith("ال") && w.length > 3 ? w.slice(2) : w);
  out.add(stripAl(word));
  if (word.startsWith("لل") && word.length > 3) out.add(word.slice(2));
  if (/^[وفبلك]/.test(word) && word.length > 2) {
    out.add(word.slice(1));
    out.add(stripAl(word.slice(1)));
  }
  return [...out];
}

function aliasOccurs(alias: string, textWords: readonly string[]): boolean {
  const aliasWords = words(alias).map((w) => (w.startsWith("ال") && w.length > 3 ? w.slice(2) : w));
  if (aliasWords.length === 0) return false;
  for (let i = 0; i + aliasWords.length <= textWords.length; i++) {
    const ok = aliasWords.every((aw, j) => {
      const tw = textWords[i + j];
      return tw !== undefined && readings(tw).includes(aw);
    });
    if (ok) return true;
  }
  return false;
}

const wordCount = (text: string) => text.trim().split(/\s+/).length;
const isUrl = (url: string) => /^https:\/\/[^\s]+$/.test(url);
const isDay = (day: string) => /^\d{4}-\d{2}-\d{2}$/.test(day);

const byId = new Map(SKILLS.map((s) => [s.id as string, s]));
const skill = (id: string) => {
  const s = byId.get(id);
  if (!s) throw new Error(`unknown skill ${id}`);
  return s;
};
const isNew = (id: string) => (WAVE3_SKILL_IDS as readonly string[]).includes(id);
function prereqsOf(id: string, seen: Set<string> = new Set()): Set<string> {
  for (const p of skill(id).prereqs) {
    if (seen.has(p)) continue;
    seen.add(p);
    prereqsOf(p, seen);
  }
  return seen;
}

const BARE_WORDS = ["تحليل", "بيانات", "تصميم", "مشروع", "إدارة", "كتابة", "تقارير", "تطوير", "تدريب", "مبيعات", "نظام", "عرض", "تقديم", "عمل", "فريق"];
const SAMPLE_SKILLS = ["excel", "sql", "statistics", "programming", "english", "communication", "presentation", "teamwork"];
const SAMPLE: Readonly<Record<string, number>> = { excel: 2, sql: 2, statistics: 1, programming: 1, english: 2, communication: 1, presentation: 1, teamwork: 1 };
const LESSONS_FOR_HOURS: Readonly<Record<number, number>> = { 6: 3, 8: 4, 10: 5, 12: 5, 14: 6, 16: 6 };
const NOT_NAJDI = ["الآن", "هذه", "لا أستطيع", "سوف", "لديك", "يمكنك", "ماذا", "إيش", "ايش", "دحين", "كدا", "عايز", "شو", "هلّق"];

// ─── fields and skills ──────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: fields and skills", () => {
  it("wires the four new fields (before professional) and the 21 new skills into the ids and the catalogue", () => {
    expect(WAVE3_FIELDS.map((f) => f.id)).toEqual(["energy-sustainability", "real-estate", "aviation", "communications"]);
    for (const f of WAVE3_FIELDS) {
      expect((FIELD_IDS as readonly string[]).includes(f.id), f.id).toBe(true);
      expect((JOB_FIELD_IDS as readonly string[]).includes(f.id), f.id).toBe(true);
    }
    expect(FIELD_IDS[FIELD_IDS.length - 1]).toBe("professional");
    expect(WAVE3_SKILLS.map((s) => s.id)).toEqual([...WAVE3_SKILL_IDS]);
    expect(new Set(WAVE3_SKILL_IDS).size).toBe(21);
    for (const s of WAVE3_SKILLS) {
      expect((SKILL_IDS as readonly string[]).includes(s.id), s.id).toBe(true);
      expect(SKILLS.find((x) => x.id === s.id), s.id).toBe(s);
      expect(wordCount(s.description), s.id).toBeLessThan(15);
    }
  });

  it("keeps prerequisites inside the field and never lets a new skill lead to a data-field skill", () => {
    for (const s of WAVE3_SKILLS) for (const p of s.prereqs) expect(skill(p).field, `${s.id} → ${p}`).toBe(s.field);
    for (const s of SKILLS.filter((x) => x.field === "data")) {
      for (const p of prereqsOf(s.id)) expect(isNew(p), `${s.id} needs ${p}`).toBe(false);
    }
  });
});

// ─── aliases ────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: aliases (rules of src/lib/data/skills.ts)", () => {
  it("gives every new skill an Arabic and an English alias, never a bare 9.2 word or a level word", () => {
    const bare = new Set(BARE_WORDS.flatMap((w) => [norm(w), norm(`ال${w}`)]));
    for (const s of WAVE3_SKILLS) {
      expect(s.aliases.some((a) => /[؀-ۿ]/.test(a)), s.id).toBe(true);
      expect(s.aliases.some((a) => /[A-Za-z]/.test(a)), s.id).toBe(true);
      for (const a of s.aliases) {
        expect(bare.has(norm(a.trim())), `${s.id}: ${a}`).toBe(false);
        expect(findKeywords(normalizeText(a), [...ADVANCED_WORDS, ...MIDDLE_WORDS]), `${s.id}: ${a}`).toEqual([]);
      }
    }
  });

  it("never gives iOS the bare «Swift» (SWIFT bank payments) nor mobile networks the English verb «RAN»", () => {
    const aliases = (id: string) => skill(id).aliases.map((a) => norm(a.trim()));
    expect(aliases("ios-swift")).not.toContain("swift");
    expect(aliases("ios-swift")).not.toContain("سويفت");
    expect(aliases("mobile-networks")).not.toContain("ran");
    // a banking CV line with SWIFT names no mobile skill
    const line = normalizeText("إعداد حوالات SWIFT ومطابقة رسائل Swift MT103 مع كشوف الحساب");
    for (const id of ["ios-swift", "flutter", "android-kotlin"]) expect(findKeywords(line, skill(id).aliases), id).toEqual([]);
  });

  it("never gives the same alias to two skills (all 114) and never reuses a company's spelling", () => {
    const owner = new Map<string, string>();
    for (const s of SKILLS) {
      for (const a of s.aliases) {
        const key = norm(a.trim());
        expect(owner.get(key) ?? s.id, `${a} in ${s.id} and ${owner.get(key) ?? ""}`).toBe(s.id);
        owner.set(key, s.id);
      }
    }
    const spellings = new Set(COMPANIES.flatMap((c) => [...c.aliases, ...(c.aliasesAlone ?? [])]).map((a) => norm(a.trim())));
    for (const s of SKILLS) for (const a of s.aliases) expect(spellings.has(norm(a.trim())), `${s.id}: ${a}`).toBe(false);
  });

  it("finds no new alias in the sample CV, which still names exactly its eight skills", () => {
    const text = words(SAMPLE_CV_BODY);
    const normalized = SAMPLE_CV_BODY.split("\n").map((line) => normalizeText(line));
    for (const s of WAVE3_SKILLS) {
      expect(s.aliases.filter((a) => aliasOccurs(a, text)), s.id).toEqual([]);
      for (const line of normalized) expect(findKeywords(line, s.aliases), `${s.id} in «${line}»`).toEqual([]);
    }
    const named = SKILLS.filter((s) => s.aliases.some((a) => aliasOccurs(a, text))).map((s) => s.id);
    expect([...named].sort()).toEqual([...SAMPLE_SKILLS].sort());
  });
});

// ─── courses ────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: courses", () => {
  it("has one course per new star slot, wired into COURSE_IDS and COURSES, 37 in all and 450 hours", () => {
    const expected = WAVE3_SKILLS.flatMap((s) => Array.from({ length: s.maxStars }, (_, i) => `c-${s.id}-${i + 1}`));
    expect(WAVE3_COURSES.map((c) => c.id)).toEqual(expected);
    expect([...WAVE3_COURSE_IDS]).toEqual(expected);
    for (const c of WAVE3_COURSES) {
      expect((COURSE_IDS as readonly string[]).includes(c.id), c.id).toBe(true);
      expect(COURSES.find((x) => x.id === c.id), c.id).toBe(c);
      expect(LESSONS_FOR_HOURS[c.hours], c.id).toBe(c.lessons.length);
      expect(c.description.split(/[.!؟]\s*/).filter((x) => x.trim().length > 0).length, c.id).toBe(2);
    }
    expect(WAVE3_COURSES).toHaveLength(37);
    expect(WAVE3_COURSES.reduce((sum, c) => sum + c.hours, 0)).toBe(450);
  });
});

// ─── jobs ───────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: real jobs", () => {
  it("lists 86 jobs once, wired into JOB_IDS and JOBS, every one after every older job (the reveal's ties stay)", () => {
    expect(WAVE3_JOBS.map((j) => j.id)).toEqual([...WAVE3_JOB_IDS]);
    expect(new Set(WAVE3_JOB_IDS).size).toBe(86);
    for (const j of WAVE3_JOBS) {
      expect((JOB_IDS as readonly string[]).includes(j.id), j.id).toBe(true);
      expect(JOBS.find((x) => x.id === j.id), j.id).toEqual({ ...j, title: cleanJobTitle(j.title) });
    }
    const first = Math.min(...WAVE3_JOB_IDS.map((id) => (JOB_IDS as readonly string[]).indexOf(id)));
    const lastOld = Math.max(...WAVE2_JOB_IDS.map((id) => (JOB_IDS as readonly string[]).indexOf(id)));
    expect(first).toBe(lastOld + 1);
    expect(JOB_IDS.slice(first, first + WAVE3_JOB_IDS.length)).toEqual([...WAVE3_JOB_IDS]); // wave 4 follows
  });

  it("gives every job five distinct requirements within the skill's stars, in roadmap order, with the posting's evidence", () => {
    for (const j of WAVE3_JOBS) {
      expect(new Set(j.requirements.map((r) => r.skill)).size, j.id).toBe(5);
      j.requirements.forEach((r, i) => {
        expect(r.stars, `${j.id}: ${r.skill}`).toBeLessThanOrEqual(skill(r.skill).maxStars);
        expect((r.evidence ?? "").length, `${j.id}: ${r.skill}`).toBeGreaterThan(0);
        for (const p of prereqsOf(r.skill)) {
          const at = j.requirements.findIndex((x) => x.skill === p);
          if (at >= 0) expect(at, `${j.id}: ${p} before ${r.skill}`).toBeLessThan(i);
        }
      });
    }
  });

  it("is a real posting from the company's own page or ATS, never LinkedIn, Indeed or Bayt, read on 21 Nov 2026", () => {
    for (const j of WAVE3_JOBS) {
      expect(j.real, j.id).toBe(true);
      expect(j.source && isUrl(j.source.url), j.id).toBe(true);
      expect(j.source?.url ?? "", j.id).not.toMatch(/linkedin\.com|indeed\.|bayt\.com/);
      expect(j.source?.checkedAt, j.id).toBe("2026-11-21");
      expect(j.band, j.id).not.toBe(undefined);
      expect(/\bsenior\b/i.test(j.titleEn ?? ""), j.id).toBe(false);
    }
  });

  it("keeps every new job under 53% with the demo's sample CV (the jobs list after the CV does not move)", () => {
    for (const j of WAVE3_JOBS) {
      const sixths = j.requirements.reduce((sum, r) => sum + (120 * Math.min(SAMPLE[r.skill] ?? 0, r.stars)) / r.stars, 0);
      expect(Math.round(sixths / 6), j.id).toBeLessThan(53);
    }
  });

  it("reads the remapped postings' new skills from their own lines (Flutter, government relations, internal comms, PR)", () => {
    const req = (id: string, s: string) => WAVE3_JOBS.find((j) => j.id === id)?.requirements.find((r) => r.skill === s);
    expect(req("lamdax-mobile-flutter-intern-remote", "flutter")?.evidence).toBe("Familiarity with Dart and Flutter, or a strong willingness to learn them.");
    expect(req("accor-government-relations-supervisor-riyadh", "government-relations")?.evidence).toContain("Qiwa, Muqeem");
    expect(WAVE3_JOBS.filter((j) => j.field === "communications").map((j) => j.id)).toEqual([
      "accor-government-relations-supervisor-riyadh",
      "qiddiya-analyst-government-relations-riyadh",
      "jodayn-tamheer-internal-communications-riyadh",
      "eram-media-content-creation-riyadh",
    ]);
  });
});

// ─── guides ─────────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: guides", () => {
  it("has one guide per new skill with real, dated links, Coursera marked paid, a certificate block, served by getGuide", () => {
    expect(WAVE3_GUIDES.map((g) => g.skill)).toEqual([...WAVE3_SKILL_IDS]);
    for (const g of WAVE3_GUIDES) {
      expect(g.alternatives.length, g.skill).toBeLessThanOrEqual(2);
      for (const c of [g.topPick, ...g.alternatives]) {
        expect(isUrl(c.url) && isDay(c.checkedAt), `${g.skill}: ${c.url}`).toBe(true);
        if (c.url.includes("coursera.org")) expect(c.price, `${g.skill}: ${c.url}`).toBe("paid");
      }
      for (const p of g.people) expect(isUrl(p.url), `${g.skill}: ${p.name}`).toBe(true);
      for (const a of g.articles) expect(isUrl(a.url), `${g.skill}: ${a.url}`).toBe(true);
      expect(g.certification, g.skill).toBeDefined();
      if (g.certification?.kind === "official") expect(isUrl(g.certification.prepUrl), g.skill).toBe(true);
      expect(getGuide(g.skill), g.skill).toBe(g);
    }
  });
});

// ─── career families and knowledge-plus ─────────────────────────────────────────────────────────────────────────────

describe("wave 3: career families (merged in ../careers.ts)", () => {
  it("adds 7 families after wave 2's (41 in all) and 9 entry routes read on official pages", () => {
    expect(WAVE3_CAREER_FAMILIES.map((f) => f.id)).toEqual([...WAVE3_FAMILY_IDS]);
    expect(CAREER_FAMILY_IDS).toHaveLength(41);
    expect(CAREER_FAMILIES.map((f) => f.id)).toEqual([...CAREER_FAMILY_IDS]);
    expect(WAVE3_ENTRY_ROUTES).toHaveLength(9);
    expect(careersIndexForModel().split("\n")).toHaveLength(41);
  });

  it("says honestly which new families have no open posting in the app yet", () => {
    expect(WAVE3_CAREER_FAMILIES.filter((f) => f.jobs.length === 0).map((f) => f.id)).toEqual(["esg-sustainability", "insurance", "telecom-network"]);
  });

  it("names only existing skills, fields, jobs and entry routes, with links on every fact and Najdi bot lines", () => {
    const routes = new Set<string>(ENTRY_ROUTES.map((r) => r.id));
    for (const f of CAREER_FAMILIES.filter((x) => (WAVE3_FAMILY_IDS as readonly string[]).includes(x.id))) {
      for (const s of f.path.skills) expect(byId.has(s), `${f.id}: ${s}`).toBe(true);
      for (const fl of f.fields) expect((FIELD_IDS as readonly string[]).includes(fl), `${f.id}: ${fl}`).toBe(true);
      for (const j of f.jobs) expect((JOB_IDS as readonly string[]).includes(j), `${f.id}: ${j}`).toBe(true);
      for (const r of f.entryRoutes) expect(routes.has(r), `${f.id}: ${r}`).toBe(true);
      for (const e of f.employers) expect(isUrl(e.careersUrl) && isDay(e.checkedAt), `${f.id}: ${e.name}`).toBe(true);
      for (const c of f.certificates) expect(isUrl(c.url), `${f.id}: ${c.name}`).toBe(true);
      if (f.salary) expect(isUrl(f.salary.url) && f.salary.minSAR < f.salary.maxSAR, f.id).toBe(true);
      expect(f.botLines.length, f.id).toBeGreaterThanOrEqual(2);
      for (const line of [...f.botLines, f.what].map((l) => l.replace(/«[^»]*»/g, ""))) {
        for (const w of NOT_NAJDI) {
          expect(words(line).includes(norm(w)) || (w.includes(" ") && line.includes(w)), `${f.id}: «${w}» in «${line}»`).toBe(false);
        }
      }
    }
    for (const r of WAVE3_ENTRY_ROUTES) {
      expect(isUrl(r.url) && isDay(r.checkedAt), r.id).toBe(true);
      if (r.fits !== "all") for (const id of r.fits) expect((CAREER_FAMILY_IDS as readonly string[]).includes(id), `${r.id}: ${id}`).toBe(true);
    }
    expect(knowledgeForModel(["aviation-ops"])).toContain("CAREER aviation-ops «");
  });

  it("merges knowledge-plus into existing families with every fact's link, and never a salary row printed in AED", () => {
    expect(WAVE3_FAMILY_PLUS.length).toBeGreaterThanOrEqual(30);
    for (const p of WAVE3_FAMILY_PLUS) {
      const f = CAREER_FAMILIES.find((x) => x.id === p.id);
      expect(f, p.id).toBeDefined();
      for (const b of p.botLines) expect(f?.botLines, p.id).toContain(b);
      for (const j of p.jobs) expect(f?.jobs, `${p.id}: ${j}`).toContain(j);
      for (const r of p.entryRoutes) expect(f?.entryRoutes, `${p.id}: ${r}`).toContain(r);
      for (const s of p.salaries) {
        expect(isUrl(s.url) && s.minSAR < s.maxSAR, `${p.id}: ${s.role}`).toBe(true);
        expect(s.sourceName, `${p.id}: ${s.role}`).not.toMatch(/Robert Walters/);
      }
      for (const q of p.interviewQuestions) expect(isUrl(q.from.url), `${p.id}: ${q.q}`).toBe(true);
      for (const d of p.localisation) for (const src of d.sources) expect(isUrl(src.url), `${p.id}: ${d.id}`).toBe(true);
      if (p.standOut) expect(isUrl(p.standOut.source.url), p.id).toBe(true);
    }
    const all = knowledgeForModel();
    expect(all).toContain("- more pay (only this source):");
    expect(all).toContain("- Saudization:");
    expect(all).not.toMatch(/Robert Walters Middle East Salary Survey/);
    // no day of collection reaches «دليلك»
    for (const text of [all, saudizationForModel()]) {
      expect(text).not.toContain("2026-11-21");
      expect(text).not.toContain("21 نوفمبر");
    }
    expect(saudizationForModel()).toContain("NITAQAT: ");
    expect(saudizationForModel()).toContain("https://laws.boe.gov.sa/");
  });
});

// ─── companies ──────────────────────────────────────────────────────────────────────────────────────────────────────

describe("wave 3: companies (the companies of the postings)", () => {
  it("knows the 34 new companies by the names their postings write, each with at least one job, and «مهارة» first on the new tiles", () => {
    expect(COMPANY_IDS).toHaveLength(141);
    const fresh = COMPANIES.filter((c) => c.checkedAt === "2026-11-21" && c.id !== "riyadh-air");
    expect(fresh).toHaveLength(34);
    for (const c of fresh) {
      expect(c.source, c.id).toBe(c.careersUrl ? "careers-page" : "posting");
      expect(jobsAtCompany(c.id).length, c.id).toBeGreaterThan(0);
    }
    const tiles: Readonly<Record<string, readonly string[]>> = COMPANY_TILES;
    for (const f of WAVE3_FIELDS) expect(tiles[f.id]?.[0], f.id).toBe("maharah");
  });
});
